input.content:
{
  "source_db": "databases/source.db",
  "target_db": "databases/target.db",
  "scope": ["customers", "orders", "order_items", "payments", "addresses"],
  "tables": {
    "customers": {"source_rows": 8000, "target_rows": 8000, "equal": true},
    "orders": {"source_rows": 50200, "target_rows": 50000, "equal": false},
    "order_items": {"source_rows": 40000, "target_rows": 40000, "equal": true},
    "payments": {"source_rows": 12000, "target_rows": 12000, "equal": true},
    "addresses": {"source_rows": 9000, "target_rows": 9000, "equal": true}
  },
  "matched": false,
  "notes": "Per docs/RECONCILIATION_CONTRACT.md, rows on record for orders are the active and archived orders together. source.db holds 50000 orders in 'orders' plus 200 in 'orders_archive' (50200 on record); target.db holds 50000 in 'orders' and 0 in 'orders_archive'. None of the 200 archived source order ids are present in target.db, so 200 orders were not carried into the migration (consistent with migrations/0002_orders_backfill.sql noting rows skipped by the loader). All other in-scope tables reconcile exactly. reconcile.py's own output reports 'MATCHED' only because it compares the 'orders' table alone (50000 vs 50000); it reports counts and does not decide the sign-off."
}

input.command:
sqlite3 "file:/testbed/migration-recon/databases/source.db?mode=ro" "ATTACH 'file:/testbed/migration-recon/databases/target.db?mode=ro' AS tgt;
SELECT 'archive ids also in source.orders:      '||COUNT(*) FROM orders_archive a WHERE EXISTS (SELECT 1 FROM orders o WHERE o.id=a.id);
SELECT 'archive ids in target.orders:           '||COUNT(*) FROM orders_archive a WHERE EXISTS (SELECT 1 FROM tgt.orders t WHERE t.id=a.id);
SELECT 'source.orders ids in target.orders:     '||COUNT(*) FROM orders o WHERE EXISTS (SELECT 1 FROM tgt.orders t WHERE t.id=o.id);
SELECT 'target.orders ids NOT in source (neither active nor archive): '||COUNT(*) FROM tgt.orders t WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.id=t.id) AND NOT EXISTS (SELECT 1 FROM orders_archive a WHERE a.id=t.id);
SELECT 'archive rows identical to their active twin: '||COUNT(*) FROM orders_archive a JOIN orders o ON o.id=a.id WHERE a.customer_id=o.customer_id AND a.total_cents=o.total_cents AND a.status=o.status AND a.created_at=o.created_at;
SELECT 'archive status breakdown: '; SELECT status||'='||COUNT(*) FROM orders_archive GROUP BY status;
SELECT 'items/payments in source referencing archived orders: '; SELECT 'order_items='||(SELECT COUNT(*) FROM order_items i WHERE i.order_id IN (SELECT id FROM orders_archive)), 'payments='||(SELECT COUNT(*) FROM payments p WHERE p.order_id IN (SELECT id FROM orders_archive));"
